//! Checked noscript markup replacement retains literal Text and native records.
use super::*;
fn fixture(raw:bool)->(Document,Forms,Page){let source="<body><noscript id=host><span id=fallback>held</span></noscript><button id=button><noscript id=guard>guarded</noscript></button><p id=out>Real</p>";let mut d=if raw{crate::html::parse_loaded_document_with_scripting(source,true,&||Ok(())).unwrap()}else{crate::html::parse(source)};d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let l=crate::navigation::address("https://noscript-markup.test/",&crate::navigation::Location::home()).unwrap();p.set_location(&l);p.set_resource_base(&l);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn noscript_inner_html_literal_parser_preprocessing_empty_clear_and_actual_records(){
 let(mut d,mut f,mut p)=fixture(true);run(&mut d,&mut f,&mut p,r#"var host=document.getElementById('host'),old=host.firstChild,oldData=old.data,watch=new MutationObserver(function(){}),raw='<img id=fake src=missing><script>window.bad=1;</script>&amp;</noscript>\r\nA\0B',expected=raw.replace('\r\n','\n').replace('\0','\ufffd');watch.observe(host,{childList:true,characterData:true,subtree:true});host.innerHTML=raw;var text=host.firstChild,rs=watch.takeRecords();if(text===old||text.nodeType!==3||text.ownerDocument!==document||text.parentNode!==host||text.data!==expected||host.textContent!==expected||host.innerHTML!==expected||old.parentNode!==null||old.data!==oldData||rs.length!==1||rs[0].type!=='childList'||rs[0].target!==host||rs[0].removedNodes[0]!==old||rs[0].addedNodes[0]!==text||document.getElementById('fake')!==null||window.bad!==undefined||document.querySelectorAll('script').length)throw 'actual literal fragment replacement';host.innerHTML='';rs=watch.takeRecords();if(host.childNodes.length||host.innerHTML!==''||text.parentNode!==null||text.data!==expected||rs.length!==1||rs[0].removedNodes[0]!==text||rs[0].addedNodes.length)throw 'actual empty markup replacement';host.innerHTML=raw;rs=watch.takeRecords();if(host.firstChild===text||host.firstChild.data!==expected||rs.length!==1||rs[0].removedNodes.length||rs[0].addedNodes[0]!==host.firstChild||window.bad!==undefined)throw 'new actual parsed raw Text';"#);assert!(p.take_dynamic_scripts().is_empty());assert!(p.take_dynamic_stylesheets().is_empty());
}
#[test]
fn noscript_inner_html_actual_nontext_and_native_ancestor_guards_refuse_atomically(){
 for raw in [false,true]{let(mut d,mut f,mut p)=fixture(raw);run(&mut d,&mut f,&mut p,"var host=document.getElementById('host'),guarded=document.getElementById('guard'),watch=new MutationObserver(function(){});watch.observe(document.body,{childList:true,characterData:true,subtree:true});");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;let values=f.controls.values().map(|c|c.value.text()).collect::<Vec<_>>();let code=if raw{"guarded.innerHTML='<img id=fake src=missing>';"}else{"host.innerHTML='changed';"};p.begin_job();let e=p.runtime.execute(code,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("inert resource subtrees"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);assert_eq!(f.controls.values().map(|c|c.value.text()).collect::<Vec<_>>(),values);p.begin_job();run(&mut d,&mut f,&mut p,"if(watch.takeRecords().length||document.getElementById('fake')!==null||window.bad!==undefined)throw 'protected markup unchanged';document.getElementById('out').textContent='Recovered';");assert!(p.take_dynamic_scripts().is_empty());assert!(p.take_dynamic_stylesheets().is_empty());}
}
#[test]
fn noscript_inner_html_quota_refusals_preserve_saved_text_records_then_recover(){
 let(mut d,mut f,mut p)=fixture(true);run(&mut d,&mut f,&mut p,"var host=document.getElementById('host'),old=host.firstChild,oldData=old.data,watch=new MutationObserver(function(){});watch.observe(host,{childList:true,characterData:true,subtree:true});");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;let limit=p.state.retained_limit;let nodes=p.state.node_limit;
 for mode in 0..4{p.begin_job();match mode{0=>p.state.copy_work=0,1=>p.state.host_work=0,2=>p.state.retained_limit=p.state.retained,_=>p.state.node_limit=d.nodes.len()};let e=p.runtime.execute("host.innerHTML='<b>literal replacement</b>';",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();let e=e.to_ascii_lowercase();assert!(match mode{0=>e.contains("dom string work limit"),1=>e.contains("dom work limit"),2=>e.contains("allowance")||e.contains("retained")||e.contains("storage"),_=>e.contains("appended-node limit")},"{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.state.retained_limit=limit;p.state.node_limit=nodes;p.begin_job();run(&mut d,&mut f,&mut p,"if(host.firstChild!==old||old.parentNode!==host||old.data!==oldData||watch.takeRecords().length)throw 'markup refusal atomic';");}
 p.begin_job();run(&mut d,&mut f,&mut p,"host.innerHTML='<b>Recovered</b>';var rs=watch.takeRecords();if(host.firstChild===old||old.parentNode!==null||host.firstChild.nodeType!==3||host.firstChild.data!=='<b>Recovered</b>'||rs.length!==1||rs[0].removedNodes[0]!==old||rs[0].addedNodes[0]!==host.firstChild)throw 'fresh raw markup recovery';");assert!(p.take_dynamic_scripts().is_empty());assert!(p.take_dynamic_stylesheets().is_empty());
}
